/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const {
		current: {
			table,
			concatenatedQuery
		},
		selectionProps,
		actionBarProps: {
			daModel: {
				count
			}
		}
	} = api.data.list_controller;
	let query = concatenatedQuery;
	const {
		sysId
	} = api.context.props;
	return {
		taskId: sysId,
		selectProps: {
			table,
			query,
			count,
			...selectionProps
		},
		attributes: null,
		action: 'certify',
		comment: null
	};
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  const selectionProps = api?.data?.list_controller?.selectionProps;
  const paginationProps = api?.data?.list_controller?.paginationProps;
  if (!Object.keys(selectionProps).length || !Object.keys(paginationProps).length)
    return helpers.translateSync('Certify');
  const {
    allRowsSelected,
    exceptedRowIds,
    selectedRowIds
  } = selectionProps;
  const {
    totalRecordCount
  } = paginationProps;

  const recordCount = allRowsSelected ? totalRecordCount - exceptedRowIds.length : selectedRowIds.length;
  if (recordCount) {
    return helpers.translateSync('Certify ({0})', recordCount);
  } else {
    return helpers.translateSync('Certify');
  }
}

