javascript(/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    const { context } = event.payload;

    if (context?.cell?.metadata?.referenceSysId) {
        context.cell.metadata.internalType = 'reference';
        context.cell.type = 'reference';
    }

    return {
        context
    };
})

